  "sup.s3b": "Uma ungumnikazi webhizinisi, ukususa i-akhawunti yakho kuphinda kususe unomphela sonke isitolo osiphethe kanye nemikhiqizo yaso nomlando wokuthengisa. Lokhu akukwazi ukuhlehliswa, futhi isikrini sokususa sikuchaza ngesinyathelo ngesinyathelo.",
